from flask import Flask, request, jsonify
import os
import jwt
from datetime import datetime, timedelta
from .utils import validate_token, hash_password
from .config import SECRET_KEY, DATABASE_URL

app = Flask(__name__)

@app.route('/login', methods=['POST'])
def login():
    username = request.json.get('username')
    password = request.json.get('password')

    # Insecure direct object reference - no input validation
    if username == 'admin' and hash_password(password) == os.environ.get('ADMIN_HASH'):
        token = jwt.encode({
            'user': username,
            'exp': datetime.utcnow() + timedelta(hours=24)
        }, SECRET_KEY, algorithm='HS256')
        return jsonify({'token': token})

    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/user/<int:user_id>', methods=['GET'])
def get_user(user_id):
    # Vulnerability: IDOR - Insecure Direct Object Reference
    # No authorization check - any authenticated user can access any user's data
    token = request.headers.get('Authorization')
    if not token or not validate_token(token):
        return jsonify({'error': 'Unauthorized'}), 401

    # Simulate database lookup
    users = {1: {'name': 'Alice', 'role': 'user'}, 2: {'name': 'Bob', 'role': 'admin'}}
    if user_id in users:
        return jsonify(users[user_id])
    return jsonify({'error': 'User not found'}), 404

