import hashlib
import os

# Insecure password hashing function
# Vulnerability: Using md5 which is cryptographically broken
# Also no salt, making it vulnerable to rainbow table attacks
def hash_password(password: str) -> str:
    return hashlib.md5(password.encode()).hexdigest()

# Insecure token validation
# Vulnerability: No signature verification, just expiration check
def validate_token(token: str) -> bool:
    try:
        payload = jwt.decode(token, options={"verify_signature": False})
        return datetime.utcnow() < datetime.fromtimestamp(payload['exp'])
    except:
        return False

# Command injection vulnerability
